PAYLOAD=''
from pathlib import Path
from datetime import datetime,timezone
import subprocess,os,json,base64,gzip,hashlib,shutil,re,shlex,secrets,difflib
ROOT=Path('/var/www/marketplace.dieseldesigns.co')
def run(args,**kw):return subprocess.run(args,check=True,**kw)
def output(args):return subprocess.check_output(args,text=True).strip()
def note(s):print(s,flush=True)
def main():
 os.chdir(ROOT)
 if output(['git','branch','--show-current'])!='main' or output(['git','status','--porcelain']):raise RuntimeError('Expected clean main branch.')
 if not output(['git','rev-parse','HEAD']).startswith('1763a82'):raise RuntimeError('Repository differs from inspected version.')
 run(['git','fetch','origin','main'])
 if output(['git','rev-parse','HEAD'])!=output(['git','rev-parse','origin/main']):raise RuntimeError('Remote main differs.')
 if datetime.now(timezone.utc)>=datetime(2026,11,1,4,tzinfo=timezone.utc):raise RuntimeError('Signup deadline has already passed. Reassess before installing.')
 manifest=json.loads(gzip.decompress(base64.b64decode(PAYLOAD)));originals={}
 for name,item in manifest.items():
  p=Path(name)
  if item['before'] is None:
   if p.exists():raise RuntimeError('Unexpected existing file: '+name)
  else:
   originals[name]=p.read_bytes()
   if hashlib.sha256(originals[name].rstrip()).hexdigest()!=item['before']:raise RuntimeError('Source differs: '+name)
 backup=ROOT/'backups'/('battle-calendar-'+datetime.now(timezone.utc).strftime('%Y%m%d-%H%M%S-%f'));stage=backup/'candidate';stage.mkdir(parents=True)
 note('BACKUP / STAGING: '+str(backup))
 for name in subprocess.check_output(['git','ls-files','-z'],text=True).split('\0'):
  if not name:continue
  p=Path(name)
  if p.parts[0] not in ('app','public','assets','database','tests','scripts','config'):continue
  target=stage/name
  if p.is_symlink():continue
  if p.is_file():target.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(p,target)
 for name,item in manifest.items():
  p=stage/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(item['content'])
  if name.endswith('.php'):run(['php','-l',str(p)])
 for suite in ['BattleOfDesignersTest','BattleUiTest']:
  p=stage/'tests'/(suite+'.php');s=p.read_text();old="require dirname(__DIR__).'/app/bootstrap.php';"
  if s.count(old)!=1:raise RuntimeError('Test bootstrap differs: '+suite)
  p.write_text(s.replace(old,"require __DIR__.'/helpers/GrandOpeningPricingBootstrap.php';"))
 m=re.search(r'(?m)^\s*(?:export\s+)?DB_NAME\s*=\s*(.*?)\s*$',Path('.env').read_text())
 if not m:raise RuntimeError('DB_NAME not found.')
 vals=shlex.split(m.group(1),comments=True)
 if len(vals)!=1 or not re.fullmatch(r'[A-Za-z0-9_]+',vals[0]):raise RuntimeError('Unexpected database name.')
 db=vals[0];mysql=['mysql','--protocol=socket','-u','root','--batch','--skip-column-names'];socket=output(mysql+['-e','SELECT @@socket'])
 if not socket or ';' in socket or '\n' in socket:raise RuntimeError('Unexpected socket.')
 if output(mysql+[db,'-e',"SHOW COLUMNS FROM battle_events LIKE 'signup_closes_at'"]):raise RuntimeError('Calendar columns already exist. Inspect before rerunning.')
 event=output(mysql+[db,'-e','SELECT CONCAT(id,"|",title,"|",status) FROM battle_events WHERE id=1'])
 if event!='1|Grand Opening|signup':raise RuntimeError('Grand Opening Battle differs from inspected event.')
 if output(mysql+[db,'-e','SELECT COUNT(*) FROM battle_rounds WHERE battle_id=1'])!='0':raise RuntimeError('Battle rounds already exist. No changes made.')
 tables=output(mysql+[db,'-e',"SELECT TABLE_NAME FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_TYPE='BASE TABLE'"]).splitlines()
 if any(not re.fullmatch(r'[A-Za-z0-9_]+',t) for t in tables):raise RuntimeError('Unexpected table name.')
 migration=manifest['database/migrations/2026_10_27_battle_event_calendar.sql']['content']
 for suite in ['BattleCalendarTest','BattleOfDesignersTest','BattleUiTest','GrandOpeningPassportTest']:
  testdb='cm_sale_test_'+secrets.token_hex(10);created=False
  try:
   note('ISOLATED TEST: '+suite+' — no live records copied')
   run(mysql+['-e','CREATE DATABASE `'+testdb+'` CHARACTER SET utf8mb4']);created=True
   run(mysql,input='\n'.join('CREATE TABLE `'+testdb+'`.`'+t+'` LIKE `'+db+'`.`'+t+'`;' for t in tables),text=True)
   run(mysql+[testdb],input=migration,text=True)
   env={'PATH':os.environ.get('PATH','/usr/bin:/bin'),'CM_SALE_TEST_DSN':'mysql:unix_socket='+socket+';dbname='+testdb}
   run(['php',str(stage/'tests'/(suite+'.php'))],env=env,cwd=stage,timeout=180)
  finally:
   if created:run(mysql+['-e','DROP DATABASE `'+testdb+'`'])
 note('ALL PRE-INSTALL CHECKS PASSED')
 for name,data in originals.items():
  if Path(name).read_bytes()!=data:raise RuntimeError('Source changed during tests: '+name)
  p=backup/'original'/name;p.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(name,p)
 with (backup/'battle-events-before.sql').open('wb') as f:run(['mysqldump','--protocol=socket','-u','root','--complete-insert',db,'battle_events'],stdout=f)
 review=[]
 for name,item in manifest.items():review.extend(difflib.unified_diff(originals.get(name,b'').decode().splitlines(keepends=True),item['content'].splitlines(keepends=True),fromfile='a/'+name,tofile='b/'+name))
 (backup/'review.diff').write_text(''.join(review))
 installed=[];altered=False
 try:
  run(mysql+[db],input=migration,text=True);altered=True
  for name,item in manifest.items():
   p=Path(name);p.parent.mkdir(parents=True,exist_ok=True)
   if name in originals and p.read_bytes()!=originals[name]:raise RuntimeError('Source changed before install: '+name)
   if name not in originals and p.exists():raise RuntimeError('File appeared before install: '+name)
   installed.append(name);temp=p.with_name(p.name+'.calendar-install');shutil.copy2(stage/name,temp);os.replace(temp,p)
  run(['git','diff','--check'])
  for name,item in manifest.items():
   if Path(name).read_text()!=item['content']:raise RuntimeError('Installed verification failed: '+name)
  result=output(mysql+[db,'-e',"UPDATE battle_events SET signup_closes_at='2026-11-01 04:00:00',first_round_opens_at='2026-11-01 17:00:00' WHERE id=1 AND status='signup' AND signup_closes_at IS NULL AND first_round_opens_at IS NULL; SELECT ROW_COUNT();"])
  if result!='1':raise RuntimeError('Battle configuration changed. Schedule was not saved.')
  saved=output(mysql+[db,'-e',"SELECT CONCAT(signup_closes_at,'|',first_round_opens_at) FROM battle_events WHERE id=1"])
  if saved!='2026-11-01 04:00:00|2026-11-01 17:00:00':raise RuntimeError('Saved schedule verification failed.')
 except Exception:
  if altered:run(mysql+[db,'-e',"UPDATE battle_events SET signup_closes_at=NULL,first_round_opens_at=NULL WHERE id=1 AND signup_closes_at='2026-11-01 04:00:00' AND first_round_opens_at='2026-11-01 17:00:00'"])
  for name in reversed(installed):
   if name in originals:shutil.copy2(backup/'original'/name,name)
   else:Path(name).unlink(missing_ok=True)
  note('Files restored; calendar disabled. Added nullable columns may remain; inspect before rerunning.')
  raise
 note('INSTALLED: signup closes end of October 31; voting starts November 1 at noon EST; consecutive 24-hour rounds.')
 note('At least two sellers are required. Ties need admin resolution; delayed tied rounds resume at the next daily noon slot.')
 note('No live emails sent by installer; scheduled Battle worker will act at the saved times.')
 note('BACKUP: '+str(backup))
 run(['git','add','--',*manifest.keys()]);run(['git','diff','--cached','--check'])
 run(['git','commit','-m','Schedule Grand Opening Battle signup cutoff and daily noon rounds'])
 run(['git','push','origin','main']);run(['git','fetch','origin','main'])
 if output(['git','rev-parse','HEAD'])!=output(['git','rev-parse','origin/main']):raise RuntimeError('Remote verification failed.')
 note('SAVED: '+output(['git','log','-1','--oneline']));note('WORKING TREE: '+(output(['git','status','--short']) or 'Clean'))
if __name__=='__main__':main()
